const value = $json.body.entry[0].changes[0].value;
const msg = value.messages[0];

return [{
  json: {
    from: msg.from,
    texto: (msg.text && msg.text.body || "").toLowerCase(),
    phoneNumberId: value.metadata.phone_number_id,
  },
}];

const { texto } = $json;

let respuesta;
if (texto.includes("tecnico") || texto.includes("técnico") || texto.includes("trabajo") || texto.includes("chamba")) {
  respuesta = "¡Hola! 👋 Soy el asistente de ChambaPe. Si quieres recibir clientes en tu zona, regístrate gratis aquí: https://chambape.pe/registrarse";
} else {
  respuesta = "¡Hola! 👋 Gracias por escribirnos a ChambaPe. Publica gratis lo que necesitas aquí: https://chambape.pe/solicitudes/nueva o regístrate como técnico aquí: https://chambape.pe/registrarse";
}

return [{ json: { ...$json, respuesta } }];
